import os
import json
from pathlib import Path

# LOADING THE FINDINGS GENERATED BY PART 2

FINDINGS_PATH = Path("narrator/findings.json")
OUTPUT_PATH = Path("narrator/sample_output.txt")

if not FINDINGS_PATH.exists():
    raise FileNotFoundError(
        "findings.json not found. Run Part 2 first."
    )

with FINDINGS_PATH.open("r", encoding="utf-8") as file:
    findings = json.load(file)

print("Task 1 complete: findings.json loaded.")


# GENERATING SCR NARRATIVE USING GEMINI

def generate_scr_narrative(findings: dict) -> dict:
    """Generate a Situation–Complication–Resolution narrative."""

    # ADDING PARAMTER LOCK ANF API KEY HANDLING

    MODEL_NAME = "gemini-2.5-flash"
    TEMPERATURE = 0.0
    MAX_OUTPUT_TOKENS = 1200
    TIMEOUT_MS = 30000

    api_key = os.environ.get("GEMINI_API_KEY")

    if not api_key:
        try:
            from google.colab import userdata
            api_key = userdata.get("GEMINI_API_KEY")
        except Exception:
            api_key = None

    # OFFLINE FALLBACK WHEN API KEY IS MISSING

    if not api_key:
        return generate_offline_narrative(findings)

    try:
        from google import genai
        from google.genai import types

        client = genai.Client(
            api_key=api_key,
            http_options=types.HttpOptions(timeout=TIMEOUT_MS)
        )

        system_instruction = """
You are a business data analyst preparing a report for Mamaearth.
Write exactly three sections: Situation, Complication, Resolution.
Use only the supplied findings and preserve all numbers accurately.
Do not invent figures, dates, or unsupported causal claims.
Give exactly three practical recommendations in Resolution.
Keep the narrative concise and business-focused.
"""

        response = client.models.generate_content(
            model=MODEL_NAME,
            contents=(
                "Create the Mamaearth SCR narrative using only these findings:\n\n"
                + json.dumps(findings, indent=2)
            ),
            config=types.GenerateContentConfig(
                system_instruction=system_instruction,
                temperature=TEMPERATURE,
                max_output_tokens=MAX_OUTPUT_TOKENS,
                thinking_config=types.ThinkingConfig(thinking_budget=0)
            )
        )

        narrative = response.text
        finish_reason = (
            response.candidates[0].finish_reason
            if response.candidates else None
        )

        if (
            not narrative
            or finish_reason == types.FinishReason.MAX_TOKENS
        ):
            fallback = generate_offline_narrative(findings)
            fallback["message"] = (
                "Gemini response incomplete; offline fallback used."
            )
            return fallback

        return {
            "status": "success",
            "narrative": narrative.strip(),
            "message": "Generated using Gemini."
        }

    except Exception as err:
        fallback = generate_offline_narrative(findings)
        fallback["message"] = (
            f"Gemini unavailable ({type(err).__name__}); "
            "offline fallback used."
        )
        return fallback


# OFFLINE NARRATIVE FUNCTION

def generate_offline_narrative(findings: dict) -> dict:
    """Generate an SCR narrative without using the Gemini API."""

    peak = findings["true_peak_month"]
    outlier = findings["outlier_inflated_month"]
    risk = findings["highest_risk_segment"]
    returns = findings["return_rate_by_payment"]

    narrative = f"""Situation
Cleaned revenue was INR {findings["cleaned_total_revenue_inr"]:,.2f},
compared with raw revenue of INR {findings["raw_total_revenue_inr"]:,.2f}.
The duplicate reconciliation delta was INR {findings["duplicate_reconciliation_delta_inr"]:,.2f}.
The true peak month was {peak["month"]}, with revenue of INR {peak["revenue_inr"]:,.2f}.

Complication
COD returns were {returns["COD"]}%, compared with {returns["CARD"]}% for CARD
and {returns["UPI"]}% for UPI. The highest-risk segment was
{risk["payment_method"]} in Tier {risk["city_tier"]}, with a
{risk["return_rate_pct"]}% return rate.
January revenue changed from INR {outlier["apparent_revenue_inr"]:,.2f}
to INR {outlier["corrected_revenue_inr"]:,.2f} after outlier correction.

Resolution
1. Reconcile duplicate records before reporting revenue.
2. Investigate COD returns in Tier 2 cities.
3. Validate bulk orders and outliers before monthly comparisons.
"""

    return {
        "status": "success",
        "narrative": narrative.strip(),
        "message": "Generated using offline fallback."
    }


# GENERATE THE NARRATIVE

result = generate_scr_narrative(findings)

if result["status"] != "success":
    raise RuntimeError(result["message"])

narrative = result["narrative"]

print("\nGeneration status:", result["status"])
print("Method:", result["message"])
print("\n===== MAMAEARTH SCR NARRATIVE =====\n")
print(narrative)



# NUMERIC ACCURACY CHECKLIST
import re

required_numbers = [
    ("Cleaned total revenue", findings["cleaned_total_revenue_inr"]),
    ("Raw total revenue", findings["raw_total_revenue_inr"]),
    ("Duplicate reconciliation delta", findings["duplicate_reconciliation_delta_inr"]),
    ("COD return rate", findings["return_rate_by_payment"]["COD"]),
    ("CARD return rate", findings["return_rate_by_payment"]["CARD"]),
    ("UPI return rate", findings["return_rate_by_payment"]["UPI"]),
    ("Highest-risk segment return rate", findings["highest_risk_segment"]["return_rate_pct"]),
    ("True peak month revenue", findings["true_peak_month"]["revenue_inr"]),
    ("January apparent revenue", findings["outlier_inflated_month"]["apparent_revenue_inr"]),
    ("January corrected revenue", findings["outlier_inflated_month"]["corrected_revenue_inr"]),
]

print("\n===== NUMERIC ACCURACY CHECKLIST =====")
numeric_pass = True

for label, expected in required_numbers:
    # Match the number whether it has one or two decimal places,
    # and whether thousands separators are present.
    expected_text = f"{expected:,.2f}"
    number_pattern = re.escape(expected_text).replace(",", r",?")
    number_pattern = number_pattern.replace(r"\.", r"\.\d*")

    # for small formatiing errors, such as 97358.3 or 97,358.30
    plain_number = f"{expected:.2f}"
    integer_part, decimal_part = plain_number.split(".")
    integer_pattern = re.escape(integer_part)
    integer_pattern = integer_pattern.replace(",", r",?")

    pattern = (
        r"(?<![\d.])"
        + integer_pattern
        + r"\.?"
        + r"\d*"
        + r"(?!\d)"
    )

    # Remove thousands separators before checking the number.
    normalized_narrative = narrative.replace(",", "")
    normalized_expected = f"{expected:.2f}"
    normalized_expected = normalized_expected.rstrip("0").rstrip(".")

    # Match the expected numeric value with optional trailing zeros.
    value_pattern = re.escape(normalized_expected)
    passed = re.search(
        r"(?<![\d.])" + value_pattern + r"0*(?!\d)",
        normalized_narrative
    ) is not None

    print(f'{"PASS" if passed else "FAIL"}: {label} — {expected}')
    numeric_pass = numeric_pass and passed

sections_pass = all(
    section in narrative
    for section in ("Situation", "Complication", "Resolution")
)

resolution = narrative.split("Resolution", 1)[1] if "Resolution" in narrative else ""
recommendations = [
    line for line in resolution.splitlines()
    if re.match(r"\s*\d+\.\s+", line)
]

print("SCR sections:", "PASS" if sections_pass else "FAIL")
print(
    "Three numbered recommendations:",
    "PASS" if len(recommendations) == 3 else "FAIL"
)

all_passed = numeric_pass and sections_pass and len(recommendations) == 3
print("\nOVERALL CHECK:", "PASS" if all_passed else "FAIL")

# SAVING THE NARRATIVE AS SAMPLE OUTPUT
OUTPUT_PATH.write_text(narrative + "\n", encoding="utf-8")
print(f"Sample output saved to: {OUTPUT_PATH}")

